{
  "shot": {
    "composition": "中景，使用50mm镜头，索尼Venice摄影机，浅景深，焦点精确对准薛夫人面部与上半身，背景中的雕花木门与庭院绿植被虚化处理，突出主体。",
    "camera_motion": "静止，无任何移动或摇晃，保持画面稳定以强调人物凝视的压迫感与仪式感。"
  },
  "subject": {
    "description": "25岁的东亚女性，面容冷艳，五官立体，眉眼深邃，眼神锐利如刀，嘴角微扬，带着一丝不易察觉的嘲讽与掌控感。发髻高挽，乌黑发丝整齐盘于头顶，无饰物，凸显其素净与威严。",
    "wardrobe": "身穿深褐色丝绸长袍，材质光滑有光泽，领口微敞，腰间系有同色系宽腰带，束紧腰身，衣袖宽大飘逸，整体造型简洁而高贵，暗含压迫感。"
  },
  "scene": {
    "location": "侯府内婚宴厅堂，雕梁画栋的木质屏风与朱红大门构成背景，厅堂两侧摆放着精致的酒席与花瓶，宾客席位隐约可见。",
    "time_of_day": "午后，阳光斜照，光线温暖而柔和。",
    "environment": "庭院内绿植环绕，枝叶投下斑驳光影，空气静谧而庄重，宾客或坐或立，气氛热闹却因薛夫人而凝滞。"
  },
  "visual_details": {
    "action": "薛夫人冷眼扫视全场，嘴角轻扬，随后缓缓举起酒杯，与宾客对饮，动作从容而精准，彰显其掌控全场的气场。",
    "props": "酒杯、酒席、雕花木门、庭院绿植、宾客席位、桌上的花瓶与餐具。",
    "action_sequence": [
      "0-1s: 薛夫人冷冽目光扫过全场宾客，嘴角微扬，眼神中透着审视与轻蔑。",
      "1-2s: 她缓缓抬起右手，拿起酒杯，杯身反射出柔和的阳光，动作优雅而缓慢。",
      "2-3s: 她将酒杯举至唇边，与宾客对视，嘴角笑意加深，眼神中暗藏锋芒。",
      "3-4s: 她轻抿一口酒，酒液在杯中荡漾，随后放下酒杯，姿态从容不迫，仿佛在掌控全场节奏。"
    ]
  },
  "cinematography": {
    "lighting": "自然午后阳光从上方斜射，光线温暖柔和，投射在薛夫人衣袍上形成细腻的光泽与阴影，背景雕花门与绿植在光线下呈现出金色与绿色的层次感。",
    "tone": "冷峻而优雅，带有戏剧张力，画面氛围庄重而神秘，突出人物的威严与掌控力，同时暗藏一丝暗流涌动的压迫感。"
  }
}
